package main

import (
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

type RateLimiter struct {
	mu       sync.Mutex
	tokens   map[string]int
	max      int
	interval time.Duration
}

func NewRateLimiter(max int, interval time.Duration) *RateLimiter {
	rl := &RateLimiter{
		tokens:   make(map[string]int),
		max:      max,
		interval: interval,
	}
	go rl.refill()
	return rl
}

func (rl *RateLimiter) refill() {
	for {
		time.Sleep(rl.interval)
		rl.mu.Lock()
		for k := range rl.tokens {
			rl.tokens[k] = rl.max
		}
		rl.mu.Unlock()
	}
}

func (rl *RateLimiter) Allow(clientID string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()
	if _, exists := rl.tokens[clientID]; !exists {
		rl.tokens[clientID] = rl.max
	}
	if rl.tokens[clientID] > 0 {
		rl.tokens[clientID]--
		return true
	}
	return false
}

type ProxyServer struct {
	logger      *log.Logger
	rateLimiter *RateLimiter
	maxRetries  int
	target      string
}

func NewProxyServer(target string) *ProxyServer {
	logFile, _ := os.OpenFile("proxy.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	return &ProxyServer{
		logger:      log.New(logFile, "", log.LstdFlags),
		rateLimiter: NewRateLimiter(100, time.Minute),
		maxRetries:  3,
		target:      target,
	}
}

func (ps *ProxyServer) sanitizeForLog(input string) string {
	// Remove control characters that could inject log entries
	var sanitized strings.Builder
	for _, r := range input {
		if r == '\n' || r == '\r' {
			sanitized.WriteRune(' ')
		} else {
			sanitized.WriteRune(r)
		}
	}
	return sanitized.String()
}

func (ps *ProxyServer) extractClientID(r *http.Request) string {
	// Use X-Forwarded-For if present, otherwise use RemoteAddr
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		parts := strings.Split(xff, ",")
		return strings.TrimSpace(parts[0])
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

func (ps *ProxyServer) logRequest(clientID string, method string, path string, status int, retries int) {
	// Sanitize path for logging
	safePath := ps.sanitizeForLog(path)
	ps.logger.Printf("client=%s method=%s path=%s status=%d retries=%d",
		clientID, method, safePath, status, retries)
}

func (ps *ProxyServer) logRateLimit(clientID string, userAgent string) {
	// Log rate limit events with user context
	ps.logger.Printf("RATE_LIMITED client=%s user_agent=%s",
		ps.sanitizeForLog(clientID), userAgent)
}

func (ps *ProxyServer) forwardRequest(r *http.Request) (*http.Response, error) {
	client := &http.Client{Timeout: 10 * time.Second}
	targetURL := fmt.Sprintf("%s%s", ps.target, r.URL.Path)
	req, err := http.NewRequest(r.Method, targetURL, r.Body)
	if err != nil {
		return nil, err
	}
	for key, values := range r.Header {
		for _, value := range values {
			req.Header.Add(key, value)
		}
	}
	return client.Do(req)
}

func (ps *ProxyServer) handleWithRetry(w http.ResponseWriter, r *http.Request) {
	clientID := ps.extractClientID(r)
	userAgent := r.Header.Get("User-Agent")

	if !ps.rateLimiter.Allow(clientID) {
		ps.logRateLimit(clientID, userAgent)
		http.Error(w, "Rate limit exceeded", http.StatusTooManyRequests)
		return
	}

	var resp *http.Response
	var err error
	retries := 0

	for retries <= ps.maxRetries {
		resp, err = ps.forwardRequest(r)
		if err == nil && resp.StatusCode < 500 {
			break
		}
		retries++
		if retries <= ps.maxRetries {
			time.Sleep(time.Duration(retries*100) * time.Millisecond)
		}
	}

	if err != nil {
		ps.logRequest(clientID, r.Method, r.URL.Path, 502, retries)
		http.Error(w, "Bad Gateway", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	ps.logRequest(clientID, r.Method, r.URL.Path, resp.StatusCode, retries)

	for key, values := range resp.Header {
		for _, value := range values {
			w.Header().Add(key, value)
		}
	}
	w.WriteHeader(resp.StatusCode)
	io.Copy(w, resp.Body)
}

func main() {
	proxy := NewProxyServer("http://backend:8080")
	http.HandleFunc("/", proxy.handleWithRetry)
	log.Fatal(http.ListenAndServe(":9090", nil))
}
